ALTER POLICY "Auth users can insert saved searches" ON public.saved_searches TO authenticated WITH CHECK (auth.uid() IS NOT NULL AND (user_id = auth.uid()::text OR user_id = public.get_customer_id(auth.uid())));
ALTER POLICY "Saved searches public read" ON public.saved_searches TO authenticated USING (user_id = auth.uid()::text OR user_id = public.get_customer_id(auth.uid()) OR public.is_admin_user(auth.uid()));
ALTER POLICY "Bookmarks are publicly readable" ON public.property_bookmarks TO authenticated USING (user_id = auth.uid()::text OR user_id = public.get_customer_id(auth.uid()) OR public.is_admin_user(auth.uid()));
ALTER POLICY "Public read social_bookmarks" ON public.social_bookmarks TO authenticated USING (user_id = auth.uid());
ALTER POLICY "Authenticated can insert reports" ON public.property_reports TO authenticated WITH CHECK (auth.uid() IS NOT NULL AND (reporter_id = auth.uid()::text OR reporter_id = public.get_customer_id(auth.uid())));
ALTER POLICY "Reports are publicly readable" ON public.property_reports TO authenticated USING (reporter_id = auth.uid()::text OR reporter_id = public.get_customer_id(auth.uid()) OR public.is_admin_user(auth.uid()));
ALTER POLICY "Authenticated can insert visits" ON public.property_visits TO authenticated WITH CHECK (auth.uid() IS NOT NULL AND (seeker_id = auth.uid()::text OR seeker_id = public.get_customer_id(auth.uid())));
ALTER POLICY "Visits are publicly readable" ON public.property_visits TO authenticated USING (seeker_id = auth.uid()::text OR seeker_id = public.get_customer_id(auth.uid()) OR public.is_admin_user(auth.uid()));
ALTER POLICY "Authenticated can insert enquiries" ON public.property_enquiries TO authenticated WITH CHECK (auth.uid() IS NOT NULL AND (seeker_id = auth.uid()::text OR seeker_id = public.get_customer_id(auth.uid())));
ALTER POLICY "Auth users can insert messages" ON public.property_messages TO authenticated WITH CHECK (auth.uid() IS NOT NULL AND (sender_id = auth.uid()::text OR sender_id = public.get_customer_id(auth.uid())));
ALTER POLICY "Website queries are publicly readable" ON public.website_queries TO authenticated USING (public.is_admin_user(auth.uid()));
ALTER POLICY "Report log is publicly readable" ON public.report_log TO authenticated USING (public.is_admin_user(auth.uid()));
ALTER POLICY "fraud_rules read" ON public.fraud_rules TO authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role));
ALTER POLICY "System inserts vendor notifications" ON public.vendor_notifications TO authenticated WITH CHECK (public.is_admin_user(auth.uid()));
ALTER POLICY "eval insert" ON public.fraud_evaluations TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));
ALTER POLICY "Auth update vendor-assets" ON storage.objects TO authenticated USING (bucket_id = 'vendor-assets' AND (owner_id = auth.uid()::text OR public.is_admin_user(auth.uid()))) WITH CHECK (bucket_id = 'vendor-assets' AND (owner_id = auth.uid()::text OR public.is_admin_user(auth.uid())));
ALTER POLICY "Auth delete vendor-assets" ON storage.objects TO authenticated USING (bucket_id = 'vendor-assets' AND (owner_id = auth.uid()::text OR public.is_admin_user(auth.uid())));
ALTER POLICY "Auth users can delete social videos" ON storage.objects TO authenticated USING (bucket_id = 'social-videos' AND (owner_id = auth.uid()::text OR public.is_admin_user(auth.uid())));
ALTER POLICY "Auth users can upload social videos" ON storage.objects TO authenticated WITH CHECK (bucket_id = 'social-videos' AND owner_id = auth.uid()::text);
ALTER POLICY "Authenticated users can upload classified images" ON storage.objects TO authenticated WITH CHECK (bucket_id = 'classified-images' AND owner_id = auth.uid()::text);
ALTER POLICY "Auth upload vendor-assets other" ON storage.objects TO authenticated WITH CHECK (bucket_id = 'vendor-assets' AND (storage.foldername(name))[1] <> 'store-logos' AND owner_id = auth.uid()::text);